"use strict";(self.webpackChunkml_seminars=self.webpackChunkml_seminars||[]).push([[978],{19:function(a){a.exports='<!DOCTYPE html>\n<html xmlns="http://www.w3.org/1999/xhtml" lang xml:lang>\n<head>\n  <meta charset="utf-8" />\n  <meta name="generator" content="pandoc" />\n  <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=yes" />\n  <title>lecture-01-intro</title>\n  <style>\nhtml {\ncolor: #1a1a1a;\nbackground-color: #fdfdfd;\n}\nbody {\nmargin: 0 auto;\nmax-width: 36em;\npadding-left: 50px;\npadding-right: 50px;\npadding-top: 50px;\npadding-bottom: 50px;\nhyphens: auto;\noverflow-wrap: break-word;\ntext-rendering: optimizeLegibility;\nfont-kerning: normal;\n}\n@media (max-width: 600px) {\nbody {\nfont-size: 0.9em;\npadding: 12px;\n}\nh1 {\nfont-size: 1.8em;\n}\n}\n@media print {\nhtml {\nbackground-color: white;\n}\nbody {\nbackground-color: transparent;\ncolor: black;\nfont-size: 12pt;\n}\np, h2, h3 {\norphans: 3;\nwidows: 3;\n}\nh2, h3, h4 {\npage-break-after: avoid;\n}\n}\np {\nmargin: 1em 0;\n}\na {\ncolor: #1a1a1a;\n}\na:visited {\ncolor: #1a1a1a;\n}\nimg {\nmax-width: 100%;\n}\nsvg {\nheight: auto;\nmax-width: 100%;\n}\nh1, h2, h3, h4, h5, h6 {\nmargin-top: 1.4em;\n}\nh5, h6 {\nfont-size: 1em;\nfont-style: italic;\n}\nh6 {\nfont-weight: normal;\n}\nol, ul {\npadding-left: 1.7em;\nmargin-top: 1em;\n}\nli > ol, li > ul {\nmargin-top: 0;\n}\nblockquote {\nmargin: 1em 0 1em 1.7em;\npadding-left: 1em;\nborder-left: 2px solid #e6e6e6;\ncolor: #606060;\n}\ncode {\nfont-family: Menlo, Monaco, Consolas, \'Lucida Console\', monospace;\nfont-size: 85%;\nmargin: 0;\nhyphens: manual;\n}\npre {\nmargin: 1em 0;\noverflow: auto;\n}\npre code {\npadding: 0;\noverflow: visible;\noverflow-wrap: normal;\n}\n.sourceCode {\nbackground-color: transparent;\noverflow: visible;\n}\nhr {\nborder: none;\nborder-top: 1px solid #1a1a1a;\nheight: 1px;\nmargin: 1em 0;\n}\ntable {\nmargin: 1em 0;\nborder-collapse: collapse;\nwidth: 100%;\noverflow-x: auto;\ndisplay: block;\nfont-variant-numeric: lining-nums tabular-nums;\n}\ntable caption {\nmargin-bottom: 0.75em;\n}\ntbody {\nmargin-top: 0.5em;\nborder-top: 1px solid #1a1a1a;\nborder-bottom: 1px solid #1a1a1a;\n}\nth {\nborder-top: 1px solid #1a1a1a;\npadding: 0.25em 0.5em 0.25em 0.5em;\n}\ntd {\npadding: 0.125em 0.5em 0.25em 0.5em;\n}\nheader {\nmargin-bottom: 4em;\ntext-align: center;\n}\n#TOC li {\nlist-style: none;\n}\n#TOC ul {\npadding-left: 1.3em;\n}\n#TOC > ul {\npadding-left: 0;\n}\n#TOC a:not(:hover) {\ntext-decoration: none;\n}\ncode{white-space: pre-wrap;}\nspan.smallcaps{font-variant: small-caps;}\ndiv.columns{display: flex; gap: min(4vw, 1.5em);}\ndiv.column{flex: auto; overflow-x: auto;}\ndiv.hanging-indent{margin-left: 1.5em; text-indent: -1.5em;}\n\nul.task-list[class]{list-style: none;}\nul.task-list li input[type="checkbox"] {\nfont-size: inherit;\nwidth: 0.8em;\nmargin: 0 0.8em 0.2em -1.6em;\nvertical-align: middle;\n}\n\nhtml { -webkit-text-size-adjust: 100%; }\npre > code.sourceCode { white-space: pre; position: relative; }\npre > code.sourceCode > span { display: inline-block; line-height: 1.25; }\npre > code.sourceCode > span:empty { height: 1.2em; }\n.sourceCode { overflow: visible; }\ncode.sourceCode > span { color: inherit; text-decoration: inherit; }\ndiv.sourceCode { margin: 1em 0; }\npre.sourceCode { margin: 0; }\n@media screen {\ndiv.sourceCode { overflow: auto; }\n}\n@media print {\npre > code.sourceCode { white-space: pre-wrap; }\npre > code.sourceCode > span { text-indent: -5em; padding-left: 5em; }\n}\npre.numberSource code\n{ counter-reset: source-line 0; }\npre.numberSource code > span\n{ position: relative; left: -4em; counter-increment: source-line; }\npre.numberSource code > span > a:first-child::before\n{ content: counter(source-line);\nposition: relative; left: -1em; text-align: right; vertical-align: baseline;\nborder: none; display: inline-block;\n-webkit-touch-callout: none; -webkit-user-select: none;\n-khtml-user-select: none; -moz-user-select: none;\n-ms-user-select: none; user-select: none;\npadding: 0 4px; width: 4em;\ncolor: #aaaaaa;\n}\npre.numberSource { margin-left: 3em; border-left: 1px solid #aaaaaa; padding-left: 4px; }\ndiv.sourceCode\n{ background-color: #f8f8f8; }\n@media screen {\npre > code.sourceCode > span > a:first-child::before { text-decoration: underline; }\n}\ncode span.al { color: #ef2929; } \ncode span.an { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.at { color: #204a87; } \ncode span.bn { color: #0000cf; } \ncode span.cf { color: #204a87; font-weight: bold; } \ncode span.ch { color: #4e9a06; } \ncode span.cn { color: #8f5902; } \ncode span.co { color: #8f5902; font-style: italic; } \ncode span.cv { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.do { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.dt { color: #204a87; } \ncode span.dv { color: #0000cf; } \ncode span.er { color: #a40000; font-weight: bold; } \ncode span.ex { } \ncode span.fl { color: #0000cf; } \ncode span.fu { color: #204a87; font-weight: bold; } \ncode span.im { } \ncode span.in { color: #8f5902; font-weight: bold; font-style: italic; } \ncode span.kw { color: #204a87; font-weight: bold; } \ncode span.op { color: #ce5c00; font-weight: bold; } \ncode span.ot { color: #8f5902; } \ncode span.pp { color: #8f5902; font-style: italic; } \ncode span.sc { color: #ce5c00; font-weight: bold; } \ncode span.ss { color: #4e9a06; } \ncode span.st { color: #4e9a06; } \ncode span.va { color: #000000; } \ncode span.vs { color: #4e9a06; } \ncode span.wa { color: #8f5902; font-weight: bold; font-style: italic; } \n</style>\n</head>\n<body>\n<div id="2d34b116" class="cell markdown">\n<h1 id="лекция-1-введение-в-машинное-обучение--демонстрации">Лекция 1.\nВведение в машинное обучение — демонстрации</h1>\n<p>Обобщающая способность, дилемма смещения–разброса, проклятие\nразмерности и неравенство Хёфдинга — всё на численных экспериментах.</p>\n<blockquote>\n<p>Ноутбук сопровождает лекцию: каждый раздел иллюстрирует кодом\nсоответствующий теоретический сюжет. Запускайте ячейки по порядку.</p>\n</blockquote>\n</div>\n<div id="cb2be6f2" class="cell code" data-execution_count="1" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T13:32:47.079931Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T13:32:47.079658Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T13:32:47.624747Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T13:32:47.624468Z&quot;}">\n<div class="sourceCode" id="cb1"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb1-1"><a href="#cb1-1" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> numpy <span class="im">as</span> np</span>\n<span id="cb1-2"><a href="#cb1-2" aria-hidden="true" tabindex="-1"></a><span class="im">import</span> matplotlib.pyplot <span class="im">as</span> plt</span>\n<span id="cb1-3"><a href="#cb1-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb1-4"><a href="#cb1-4" aria-hidden="true" tabindex="-1"></a><span class="op">%</span>matplotlib inline</span>\n<span id="cb1-5"><a href="#cb1-5" aria-hidden="true" tabindex="-1"></a>plt.rcParams.update({</span>\n<span id="cb1-6"><a href="#cb1-6" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.figsize&quot;</span>: (<span class="dv">7</span>, <span class="dv">4</span>),</span>\n<span id="cb1-7"><a href="#cb1-7" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;figure.dpi&quot;</span>: <span class="dv">110</span>,</span>\n<span id="cb1-8"><a href="#cb1-8" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;axes.grid&quot;</span>: <span class="va">True</span>,</span>\n<span id="cb1-9"><a href="#cb1-9" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;grid.alpha&quot;</span>: <span class="fl">0.25</span>,</span>\n<span id="cb1-10"><a href="#cb1-10" aria-hidden="true" tabindex="-1"></a>    <span class="st">&quot;font.size&quot;</span>: <span class="dv">11</span>,</span>\n<span id="cb1-11"><a href="#cb1-11" aria-hidden="true" tabindex="-1"></a>})</span>\n<span id="cb1-12"><a href="#cb1-12" aria-hidden="true" tabindex="-1"></a>RANDOM_STATE <span class="op">=</span> <span class="dv">42</span></span>\n<span id="cb1-13"><a href="#cb1-13" aria-hidden="true" tabindex="-1"></a>rng <span class="op">=</span> np.random.default_rng(RANDOM_STATE)</span></code></pre></div>\n</div>\n<div id="63d0d98a" class="cell markdown">\n<h2 id="1-обобщающая-способность-почему-нельзя-верить-ошибке-на-обучении">1.\nОбобщающая способность: почему нельзя верить ошибке на обучении</h2>\n<p>Мы минимизируем <strong>эмпирический риск</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mover><mi>Q</mi><mo accent="true">̂</mo></mover><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><mfrac><mn>1</mn><mi>n</mi></mfrac><msub><mo>∑</mo><mi>i</mi></msub><mi>L</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><msub><mi>x</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo><mo>,</mo><msub><mi>y</mi><mi>i</mi></msub><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">\\hat{Q}(a) = \\frac{1}{n}\\sum_i L(a(x_i), y_i)</annotation></semantics></math>,\nа интересует нас <strong>истинный риск</strong>\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="postfix">)</mo><mo>=</mo><msub><mi>𝔼</mi><mrow><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow></msub><mi>L</mi><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>,</mo><mi>y</mi><mo stretchy="false" form="postfix">)</mo></mrow><annotation encoding="application/x-tex">Q(a) = \\mathbb{E}_{(x,y)} L(a(x), y)</annotation></semantics></math>.\nЧем сложнее модель, тем сильнее эти величины расходятся.</p>\n</div>\n<div id="a920bbd5" class="cell code" data-execution_count="2" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T13:32:47.626279Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T13:32:47.626148Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T13:32:50.103152Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T13:32:50.102900Z&quot;}">\n<div class="sourceCode" id="cb2"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb2-1"><a href="#cb2-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> PolynomialFeatures</span>\n<span id="cb2-2"><a href="#cb2-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LinearRegression</span>\n<span id="cb2-3"><a href="#cb2-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.pipeline <span class="im">import</span> make_pipeline</span>\n<span id="cb2-4"><a href="#cb2-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> train_test_split</span>\n<span id="cb2-5"><a href="#cb2-5" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.metrics <span class="im">import</span> mean_squared_error</span>\n<span id="cb2-6"><a href="#cb2-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-7"><a href="#cb2-7" aria-hidden="true" tabindex="-1"></a><span class="kw">def</span> true_function(x):</span>\n<span id="cb2-8"><a href="#cb2-8" aria-hidden="true" tabindex="-1"></a>    <span class="cf">return</span> np.sin(<span class="fl">1.5</span> <span class="op">*</span> np.pi <span class="op">*</span> x)</span>\n<span id="cb2-9"><a href="#cb2-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-10"><a href="#cb2-10" aria-hidden="true" tabindex="-1"></a>n <span class="op">=</span> <span class="dv">40</span></span>\n<span id="cb2-11"><a href="#cb2-11" aria-hidden="true" tabindex="-1"></a>X <span class="op">=</span> rng.uniform(<span class="dv">0</span>, <span class="dv">1</span>, n).reshape(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)</span>\n<span id="cb2-12"><a href="#cb2-12" aria-hidden="true" tabindex="-1"></a>y <span class="op">=</span> true_function(X).ravel() <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.25</span>, n)</span>\n<span id="cb2-13"><a href="#cb2-13" aria-hidden="true" tabindex="-1"></a>X_tr, X_te, y_tr, y_te <span class="op">=</span> train_test_split(X, y, test_size<span class="op">=</span><span class="fl">0.4</span>, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb2-14"><a href="#cb2-14" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-15"><a href="#cb2-15" aria-hidden="true" tabindex="-1"></a>grid <span class="op">=</span> np.linspace(<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">300</span>).reshape(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)</span>\n<span id="cb2-16"><a href="#cb2-16" aria-hidden="true" tabindex="-1"></a>degrees <span class="op">=</span> [<span class="dv">1</span>, <span class="dv">4</span>, <span class="dv">15</span>]</span>\n<span id="cb2-17"><a href="#cb2-17" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb2-18"><a href="#cb2-18" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">3</span>, figsize<span class="op">=</span>(<span class="dv">12</span>, <span class="fl">3.6</span>), sharey<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb2-19"><a href="#cb2-19" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, d <span class="kw">in</span> <span class="bu">zip</span>(axes, degrees):</span>\n<span id="cb2-20"><a href="#cb2-20" aria-hidden="true" tabindex="-1"></a>    model <span class="op">=</span> make_pipeline(PolynomialFeatures(d), LinearRegression()).fit(X_tr, y_tr)</span>\n<span id="cb2-21"><a href="#cb2-21" aria-hidden="true" tabindex="-1"></a>    ax.plot(grid, true_function(grid), color<span class="op">=</span><span class="st">&quot;#0f172a&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;истинная зависимость&quot;</span>)</span>\n<span id="cb2-22"><a href="#cb2-22" aria-hidden="true" tabindex="-1"></a>    ax.plot(grid, model.predict(grid), color<span class="op">=</span><span class="st">&quot;#7c3aed&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;модель&quot;</span>)</span>\n<span id="cb2-23"><a href="#cb2-23" aria-hidden="true" tabindex="-1"></a>    ax.scatter(X_tr, y_tr, s<span class="op">=</span><span class="dv">28</span>, color<span class="op">=</span><span class="st">&quot;#06b6d4&quot;</span>, zorder<span class="op">=</span><span class="dv">3</span>, label<span class="op">=</span><span class="st">&quot;обучение&quot;</span>)</span>\n<span id="cb2-24"><a href="#cb2-24" aria-hidden="true" tabindex="-1"></a>    ax.scatter(X_te, y_te, s<span class="op">=</span><span class="dv">28</span>, color<span class="op">=</span><span class="st">&quot;#f59e0b&quot;</span>, zorder<span class="op">=</span><span class="dv">3</span>, label<span class="op">=</span><span class="st">&quot;контроль&quot;</span>)</span>\n<span id="cb2-25"><a href="#cb2-25" aria-hidden="true" tabindex="-1"></a>    ax.set_ylim(<span class="op">-</span><span class="dv">2</span>, <span class="dv">2</span>)</span>\n<span id="cb2-26"><a href="#cb2-26" aria-hidden="true" tabindex="-1"></a>    ax.set_title(<span class="ss">f&quot;степень </span><span class="sc">{</span>d<span class="sc">}</span><span class="ch">\\n</span><span class="ss">train MSE=</span><span class="sc">{</span>mean_squared_error(y_tr, model.predict(X_tr))<span class="sc">:.3f}</span><span class="ss">, &quot;</span></span>\n<span id="cb2-27"><a href="#cb2-27" aria-hidden="true" tabindex="-1"></a>                 <span class="ss">f&quot;test MSE=</span><span class="sc">{</span>mean_squared_error(y_te, model.predict(X_te))<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb2-28"><a href="#cb2-28" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb2-29"><a href="#cb2-29" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()</span>\n<span id="cb2-30"><a href="#cb2-30" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n<div class="output display_data">\n<p><img role="img" src="data:image/png;base64," /></p>\n</div>\n</div>\n<div id="f34ae441" class="cell markdown">\n<p>Слева — недообучение: модель слишком проста, ошибка велика везде.\nСправа — переобучение: на обучении почти ноль, на контроле\nкатастрофа.</p>\n</div>\n<div id="7fd23e14" class="cell markdown">\n<h2 id="2-дилемма-смещенияразброса">2. Дилемма смещения–разброса</h2>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>𝔼</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">[</mo><mo stretchy="false" form="prefix">(</mo><mi>y</mi><mo>−</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">]</mo><mo>=</mo><munder><munder><mrow><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mi>𝔼</mi><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>f</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mn>2</mn></msup></mrow><mo accent="true">⏟</mo></munder><msup><mtext mathvariant="normal">смещение</mtext><mn>2</mn></msup></munder><mo>+</mo><munder><munder><mrow><mi>𝔼</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">[</mo><mo stretchy="false" form="prefix">(</mo><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><mo>−</mo><mi>𝔼</mi><mi>a</mi><mo stretchy="false" form="prefix">(</mo><mi>x</mi><mo stretchy="false" form="postfix">)</mo><msup><mo stretchy="false" form="postfix">)</mo><mn>2</mn></msup><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">]</mo></mrow><mo accent="true">⏟</mo></munder><mtext mathvariant="normal">разброс</mtext></munder><mo>+</mo><msup><mi>σ</mi><mn>2</mn></msup><mi>.</mi></mrow><annotation encoding="application/x-tex">\\mathbb{E}\\bigl[(y - a(x))^2\\bigr] = \\underbrace{\\bigl(\\mathbb{E}a(x) - f(x)\\bigr)^2}_{\\text{смещение}^2}\n+ \\underbrace{\\mathbb{E}\\bigl[(a(x) - \\mathbb{E}a(x))^2\\bigr]}_{\\text{разброс}} + \\sigma^2.</annotation></semantics></math></p>\n<p>Оценим смещение и разброс <strong>эмпирически</strong>: обучим модель\nна 200 независимых выборках и посмотрим на разброс предсказаний в\nфиксированной точке.</p>\n</div>\n<div id="9f86e324" class="cell code" data-execution_count="3" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T13:32:50.104456Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T13:32:50.104326Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T13:32:50.328271Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T13:32:50.328019Z&quot;}">\n<div class="sourceCode" id="cb3"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb3-1"><a href="#cb3-1" aria-hidden="true" tabindex="-1"></a>n_datasets, n_points <span class="op">=</span> <span class="dv">200</span>, <span class="dv">30</span></span>\n<span id="cb3-2"><a href="#cb3-2" aria-hidden="true" tabindex="-1"></a>x_query <span class="op">=</span> np.linspace(<span class="dv">0</span>, <span class="dv">1</span>, <span class="dv">100</span>).reshape(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)</span>\n<span id="cb3-3"><a href="#cb3-3" aria-hidden="true" tabindex="-1"></a>results <span class="op">=</span> {}</span>\n<span id="cb3-4"><a href="#cb3-4" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-5"><a href="#cb3-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> d <span class="kw">in</span> [<span class="dv">1</span>, <span class="dv">4</span>, <span class="dv">15</span>]:</span>\n<span id="cb3-6"><a href="#cb3-6" aria-hidden="true" tabindex="-1"></a>    preds <span class="op">=</span> np.zeros((n_datasets, <span class="bu">len</span>(x_query)))</span>\n<span id="cb3-7"><a href="#cb3-7" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> k <span class="kw">in</span> <span class="bu">range</span>(n_datasets):</span>\n<span id="cb3-8"><a href="#cb3-8" aria-hidden="true" tabindex="-1"></a>        Xk <span class="op">=</span> rng.uniform(<span class="dv">0</span>, <span class="dv">1</span>, n_points).reshape(<span class="op">-</span><span class="dv">1</span>, <span class="dv">1</span>)</span>\n<span id="cb3-9"><a href="#cb3-9" aria-hidden="true" tabindex="-1"></a>        yk <span class="op">=</span> true_function(Xk).ravel() <span class="op">+</span> rng.normal(<span class="dv">0</span>, <span class="fl">0.25</span>, n_points)</span>\n<span id="cb3-10"><a href="#cb3-10" aria-hidden="true" tabindex="-1"></a>        model <span class="op">=</span> make_pipeline(PolynomialFeatures(d), LinearRegression()).fit(Xk, yk)</span>\n<span id="cb3-11"><a href="#cb3-11" aria-hidden="true" tabindex="-1"></a>        preds[k] <span class="op">=</span> model.predict(x_query)</span>\n<span id="cb3-12"><a href="#cb3-12" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb3-13"><a href="#cb3-13" aria-hidden="true" tabindex="-1"></a>    bias2 <span class="op">=</span> np.mean((preds.mean(axis<span class="op">=</span><span class="dv">0</span>) <span class="op">-</span> true_function(x_query).ravel()) <span class="op">**</span> <span class="dv">2</span>)</span>\n<span id="cb3-14"><a href="#cb3-14" aria-hidden="true" tabindex="-1"></a>    variance <span class="op">=</span> np.mean(preds.var(axis<span class="op">=</span><span class="dv">0</span>))</span>\n<span id="cb3-15"><a href="#cb3-15" aria-hidden="true" tabindex="-1"></a>    results[d] <span class="op">=</span> (preds, bias2, variance)</span>\n<span id="cb3-16"><a href="#cb3-16" aria-hidden="true" tabindex="-1"></a>    <span class="bu">print</span>(<span class="ss">f&quot;степень </span><span class="sc">{</span>d<span class="sc">:2d}</span><span class="ss">:  смещение² = </span><span class="sc">{</span>bias2<span class="sc">:.4f}</span><span class="ss">   разброс = </span><span class="sc">{</span>variance<span class="sc">:.4f}</span><span class="ss">   сумма = </span><span class="sc">{</span>bias2 <span class="op">+</span> variance<span class="sc">:.4f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n<div class="output stream stdout">\n<pre><code>степень  1:  смещение² = 0.1863   разброс = 0.0212   сумма = 0.2076\nстепень  4:  смещение² = 0.0003   разброс = 0.0188   сумма = 0.0191\nстепень 15:  смещение² = 308093.5679   разброс = 156025412.8380   сумма = 156333506.4059\n</code></pre>\n</div>\n</div>\n<div id="892e512a" class="cell code" data-execution_count="4" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T13:32:50.329542Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T13:32:50.329465Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T13:32:50.491187Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T13:32:50.490957Z&quot;}">\n<div class="sourceCode" id="cb5"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb5-1"><a href="#cb5-1" aria-hidden="true" tabindex="-1"></a>fig, axes <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">3</span>, figsize<span class="op">=</span>(<span class="dv">12</span>, <span class="fl">3.6</span>), sharey<span class="op">=</span><span class="va">True</span>)</span>\n<span id="cb5-2"><a href="#cb5-2" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> ax, (d, (preds, bias2, variance)) <span class="kw">in</span> <span class="bu">zip</span>(axes, results.items()):</span>\n<span id="cb5-3"><a href="#cb5-3" aria-hidden="true" tabindex="-1"></a>    <span class="cf">for</span> row <span class="kw">in</span> preds[:<span class="dv">40</span>]:</span>\n<span id="cb5-4"><a href="#cb5-4" aria-hidden="true" tabindex="-1"></a>        ax.plot(x_query, row, color<span class="op">=</span><span class="st">&quot;#7c3aed&quot;</span>, alpha<span class="op">=</span><span class="fl">0.12</span>, lw<span class="op">=</span><span class="dv">1</span>)</span>\n<span id="cb5-5"><a href="#cb5-5" aria-hidden="true" tabindex="-1"></a>    ax.plot(x_query, preds.mean(axis<span class="op">=</span><span class="dv">0</span>), color<span class="op">=</span><span class="st">&quot;#7c3aed&quot;</span>, lw<span class="op">=</span><span class="fl">2.5</span>, label<span class="op">=</span><span class="st">&quot;среднее предсказание&quot;</span>)</span>\n<span id="cb5-6"><a href="#cb5-6" aria-hidden="true" tabindex="-1"></a>    ax.plot(x_query, true_function(x_query), color<span class="op">=</span><span class="st">&quot;#0f172a&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, ls<span class="op">=</span><span class="st">&quot;--&quot;</span>, label<span class="op">=</span><span class="st">&quot;истина&quot;</span>)</span>\n<span id="cb5-7"><a href="#cb5-7" aria-hidden="true" tabindex="-1"></a>    ax.set_ylim(<span class="op">-</span><span class="fl">2.2</span>, <span class="fl">2.2</span>)</span>\n<span id="cb5-8"><a href="#cb5-8" aria-hidden="true" tabindex="-1"></a>    ax.set_title(<span class="ss">f&quot;степень </span><span class="sc">{</span>d<span class="sc">}</span><span class="ch">\\n</span><span class="ss">смещение²=</span><span class="sc">{</span>bias2<span class="sc">:.3f}</span><span class="ss">, разброс=</span><span class="sc">{</span>variance<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb5-9"><a href="#cb5-9" aria-hidden="true" tabindex="-1"></a>axes[<span class="dv">0</span>].legend(fontsize<span class="op">=</span><span class="dv">8</span>)</span>\n<span id="cb5-10"><a href="#cb5-10" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()</span>\n<span id="cb5-11"><a href="#cb5-11" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n<div class="output display_data">\n<p><img role="img" src="data:image/png;base64," /></p>\n</div>\n</div>\n<div id="e3ecc758" class="cell markdown">\n<p>Простая модель (слева) даёт почти одинаковые предсказания на разных\nвыборках — разброс мал, но систематически промахивается. Сложная\n(справа) в среднем попадает верно, но «болтается» от выборки к выборке.\nЭто и есть компромисс.</p>\n</div>\n<div id="a96e1f7d" class="cell markdown">\n<h2 id="3-проклятие-размерности">3. Проклятие размерности</h2>\n<p>В высокой размерности почти весь объём шара сосредоточен у\nповерхности, а все попарные расстояния становятся почти одинаковыми —\nметрические методы теряют смысл.</p>\n<p>Доля объёма шара радиуса 1 в слое толщины\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ε</mi><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math>\nу границы:\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>1</mn><mo>−</mo><mo stretchy="false" form="prefix">(</mo><mn>1</mn><mo>−</mo><mi>ε</mi><msup><mo stretchy="false" form="postfix">)</mo><mi>p</mi></msup><mo>→</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">1 - (1-\\varepsilon)^p \\to 1</annotation></semantics></math>\nпри\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>p</mi><mo>→</mo><mi>∞</mi></mrow><annotation encoding="application/x-tex">p \\to \\infty</annotation></semantics></math>.</p>\n</div>\n<div id="b8767d82" class="cell code" data-execution_count="5" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T13:32:50.492474Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T13:32:50.492376Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T13:32:50.745772Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T13:32:50.745507Z&quot;}">\n<div class="sourceCode" id="cb6"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb6-1"><a href="#cb6-1" aria-hidden="true" tabindex="-1"></a>fig, (ax1, ax2) <span class="op">=</span> plt.subplots(<span class="dv">1</span>, <span class="dv">2</span>, figsize<span class="op">=</span>(<span class="dv">12</span>, <span class="fl">3.8</span>))</span>\n<span id="cb6-2"><a href="#cb6-2" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-3"><a href="#cb6-3" aria-hidden="true" tabindex="-1"></a><span class="co"># Слева: доля объёма в приграничном слое</span></span>\n<span id="cb6-4"><a href="#cb6-4" aria-hidden="true" tabindex="-1"></a>p_values <span class="op">=</span> np.arange(<span class="dv">1</span>, <span class="dv">51</span>)</span>\n<span id="cb6-5"><a href="#cb6-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> eps <span class="kw">in</span> [<span class="fl">0.01</span>, <span class="fl">0.05</span>, <span class="fl">0.1</span>]:</span>\n<span id="cb6-6"><a href="#cb6-6" aria-hidden="true" tabindex="-1"></a>    ax1.plot(p_values, <span class="dv">1</span> <span class="op">-</span> (<span class="dv">1</span> <span class="op">-</span> eps) <span class="op">**</span> p_values, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="ss">f&quot;слой толщины </span><span class="sc">{</span>eps<span class="sc">}</span><span class="ss">&quot;</span>)</span>\n<span id="cb6-7"><a href="#cb6-7" aria-hidden="true" tabindex="-1"></a>ax1.set_xlabel(<span class="st">&quot;размерность $p$&quot;</span>)<span class="op">;</span> ax1.set_ylabel(<span class="st">&quot;доля объёма шара&quot;</span>)</span>\n<span id="cb6-8"><a href="#cb6-8" aria-hidden="true" tabindex="-1"></a>ax1.set_title(<span class="st">&quot;Объём уходит на поверхность&quot;</span>)</span>\n<span id="cb6-9"><a href="#cb6-9" aria-hidden="true" tabindex="-1"></a>ax1.legend()</span>\n<span id="cb6-10"><a href="#cb6-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-11"><a href="#cb6-11" aria-hidden="true" tabindex="-1"></a><span class="co"># Справа: концентрация расстояний</span></span>\n<span id="cb6-12"><a href="#cb6-12" aria-hidden="true" tabindex="-1"></a>dims, ratios <span class="op">=</span> <span class="bu">range</span>(<span class="dv">1</span>, <span class="dv">101</span>, <span class="dv">5</span>), []</span>\n<span id="cb6-13"><a href="#cb6-13" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> p <span class="kw">in</span> dims:</span>\n<span id="cb6-14"><a href="#cb6-14" aria-hidden="true" tabindex="-1"></a>    pts <span class="op">=</span> rng.normal(size<span class="op">=</span>(<span class="dv">200</span>, p))</span>\n<span id="cb6-15"><a href="#cb6-15" aria-hidden="true" tabindex="-1"></a>    d <span class="op">=</span> np.sqrt(((pts[:, <span class="va">None</span>, :] <span class="op">-</span> pts[<span class="va">None</span>, :, :]) <span class="op">**</span> <span class="dv">2</span>).<span class="bu">sum</span>(axis<span class="op">=</span><span class="dv">2</span>))</span>\n<span id="cb6-16"><a href="#cb6-16" aria-hidden="true" tabindex="-1"></a>    d <span class="op">=</span> d[np.triu_indices(<span class="bu">len</span>(pts), k<span class="op">=</span><span class="dv">1</span>)]</span>\n<span id="cb6-17"><a href="#cb6-17" aria-hidden="true" tabindex="-1"></a>    ratios.append((d.<span class="bu">max</span>() <span class="op">-</span> d.<span class="bu">min</span>()) <span class="op">/</span> d.<span class="bu">min</span>())</span>\n<span id="cb6-18"><a href="#cb6-18" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb6-19"><a href="#cb6-19" aria-hidden="true" tabindex="-1"></a>ax2.plot(<span class="bu">list</span>(dims), ratios, marker<span class="op">=</span><span class="st">&quot;o&quot;</span>, color<span class="op">=</span><span class="st">&quot;#7c3aed&quot;</span>)</span>\n<span id="cb6-20"><a href="#cb6-20" aria-hidden="true" tabindex="-1"></a>ax2.set_xlabel(<span class="st">&quot;размерность $p$&quot;</span>)<span class="op">;</span> ax2.set_ylabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="kw">(</span><span class="vs">d_{max} - d_{min}</span><span class="kw">)</span><span class="vs"> / d_{min}</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb6-21"><a href="#cb6-21" aria-hidden="true" tabindex="-1"></a>ax2.set_title(<span class="st">&quot;Расстояния становятся неразличимы&quot;</span>)</span>\n<span id="cb6-22"><a href="#cb6-22" aria-hidden="true" tabindex="-1"></a>plt.tight_layout()</span>\n<span id="cb6-23"><a href="#cb6-23" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n<div class="output display_data">\n<p><img role="img" src="data:image/png;base64," /></p>\n</div>\n</div>\n<div id="0cc2d2a8" class="cell markdown">\n<h2 id="4-неравенство-хёфдинга">4. Неравенство Хёфдинга</h2>\n<p>Для ограниченных потерь\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>L</mi><mo>∈</mo><mo stretchy="false" form="prefix">[</mo><mn>0</mn><mo>,</mo><mn>1</mn><mo stretchy="false" form="postfix">]</mo></mrow><annotation encoding="application/x-tex">L \\in [0, 1]</annotation></semantics></math>\nи фиксированного алгоритма</p>\n<p><math display="block" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="prefix">(</mo><mo stretchy="false" form="prefix">|</mo><mover><mi>Q</mi><mo accent="true">̂</mo></mover><mo>−</mo><mi>Q</mi><mo stretchy="false" form="prefix">|</mo><mo>&gt;</mo><mi>ε</mi><mo minsize="120%" maxsize="120%" stretchy="true" form="postfix">)</mo><mo>≤</mo><mn>2</mn><msup><mi>e</mi><mrow><mi>−</mi><mn>2</mn><mi>n</mi><msup><mi>ε</mi><mn>2</mn></msup></mrow></msup><mi>.</mi></mrow><annotation encoding="application/x-tex">P\\bigl(|\\hat{Q} - Q| &gt; \\varepsilon\\bigr) \\le 2e^{-2n\\varepsilon^2}.</annotation></semantics></math></p>\n<p>Проверим границу численно: многократно оценим долю ошибок на выборке\nразмера\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>n</mi><annotation encoding="application/x-tex">n</annotation></semantics></math>\nи посмотрим, как часто отклонение превышает\n<math display="inline" xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mi>ε</mi><annotation encoding="application/x-tex">\\varepsilon</annotation></semantics></math>.</p>\n</div>\n<div id="dd0c8659" class="cell code" data-execution_count="6" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T13:32:50.747350Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T13:32:50.747238Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T13:32:50.854565Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T13:32:50.854340Z&quot;}">\n<div class="sourceCode" id="cb7"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb7-1"><a href="#cb7-1" aria-hidden="true" tabindex="-1"></a>true_error, eps, n_trials <span class="op">=</span> <span class="fl">0.3</span>, <span class="fl">0.05</span>, <span class="dv">5000</span></span>\n<span id="cb7-2"><a href="#cb7-2" aria-hidden="true" tabindex="-1"></a>sizes <span class="op">=</span> [<span class="dv">50</span>, <span class="dv">100</span>, <span class="dv">200</span>, <span class="dv">400</span>, <span class="dv">800</span>]</span>\n<span id="cb7-3"><a href="#cb7-3" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-4"><a href="#cb7-4" aria-hidden="true" tabindex="-1"></a>empirical, bound <span class="op">=</span> [], []</span>\n<span id="cb7-5"><a href="#cb7-5" aria-hidden="true" tabindex="-1"></a><span class="cf">for</span> n_size <span class="kw">in</span> sizes:</span>\n<span id="cb7-6"><a href="#cb7-6" aria-hidden="true" tabindex="-1"></a>    hats <span class="op">=</span> rng.binomial(n_size, true_error, size<span class="op">=</span>n_trials) <span class="op">/</span> n_size</span>\n<span id="cb7-7"><a href="#cb7-7" aria-hidden="true" tabindex="-1"></a>    empirical.append(np.mean(np.<span class="bu">abs</span>(hats <span class="op">-</span> true_error) <span class="op">&gt;</span> eps))</span>\n<span id="cb7-8"><a href="#cb7-8" aria-hidden="true" tabindex="-1"></a>    bound.append(<span class="bu">min</span>(<span class="fl">1.0</span>, <span class="dv">2</span> <span class="op">*</span> np.exp(<span class="op">-</span><span class="dv">2</span> <span class="op">*</span> n_size <span class="op">*</span> eps <span class="op">**</span> <span class="dv">2</span>)))</span>\n<span id="cb7-9"><a href="#cb7-9" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb7-10"><a href="#cb7-10" aria-hidden="true" tabindex="-1"></a>plt.semilogy(sizes, bound, marker<span class="op">=</span><span class="st">&quot;s&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;граница Хёфдинга&quot;</span>)</span>\n<span id="cb7-11"><a href="#cb7-11" aria-hidden="true" tabindex="-1"></a>plt.semilogy(sizes, np.maximum(empirical, <span class="fl">1e-4</span>), marker<span class="op">=</span><span class="st">&quot;o&quot;</span>, lw<span class="op">=</span><span class="dv">2</span>, label<span class="op">=</span><span class="st">&quot;эмпирическая частота&quot;</span>)</span>\n<span id="cb7-12"><a href="#cb7-12" aria-hidden="true" tabindex="-1"></a>plt.xlabel(<span class="st">&quot;размер выборки $n$&quot;</span>)<span class="op">;</span> plt.ylabel(<span class="vs">r&quot;</span><span class="dv">$</span><span class="vs">P</span><span class="kw">(</span><span class="cf">|</span><span class="er">\\</span><span class="vs">hat{Q} - Q</span><span class="cf">|</span><span class="vs"> &gt; 0</span><span class="dv">.</span><span class="vs">05</span><span class="kw">)</span><span class="dv">$</span><span class="vs">&quot;</span>)</span>\n<span id="cb7-13"><a href="#cb7-13" aria-hidden="true" tabindex="-1"></a>plt.title(<span class="st">&quot;Неравенство Хёфдинга: граница и реальность&quot;</span>)</span>\n<span id="cb7-14"><a href="#cb7-14" aria-hidden="true" tabindex="-1"></a>plt.legend()</span>\n<span id="cb7-15"><a href="#cb7-15" aria-hidden="true" tabindex="-1"></a>plt.show()</span></code></pre></div>\n<div class="output display_data">\n<p><img role="img" src="data:image/png;base64," /></p>\n</div>\n</div>\n<div id="7630d0cd" class="cell markdown">\n<p>Граница выполняется с большим запасом — она справедлива для\n<strong>любого</strong> распределения, поэтому неизбежно консервативна.\nПрактический вывод тот же: чем больше выборка, тем надёжнее эмпирическая\nоценка качества.</p>\n</div>\n<div id="8559f1f1" class="cell markdown">\n<h2 id="5-схема-эксперимента">5. Схема эксперимента</h2>\n<p>Правильный порядок работы, к которому мы будем возвращаться весь\nкурс:</p>\n</div>\n<div id="1e909029" class="cell code" data-execution_count="7" data-execution="{&quot;iopub.execute_input&quot;:&quot;2026-07-28T13:32:50.855928Z&quot;,&quot;iopub.status.busy&quot;:&quot;2026-07-28T13:32:50.855832Z&quot;,&quot;iopub.status.idle&quot;:&quot;2026-07-28T13:32:50.982177Z&quot;,&quot;shell.execute_reply&quot;:&quot;2026-07-28T13:32:50.981336Z&quot;}">\n<div class="sourceCode" id="cb8"><pre class="sourceCode python"><code class="sourceCode python"><span id="cb8-1"><a href="#cb8-1" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.model_selection <span class="im">import</span> cross_val_score, KFold</span>\n<span id="cb8-2"><a href="#cb8-2" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.datasets <span class="im">import</span> load_breast_cancer</span>\n<span id="cb8-3"><a href="#cb8-3" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.preprocessing <span class="im">import</span> StandardScaler</span>\n<span id="cb8-4"><a href="#cb8-4" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.linear_model <span class="im">import</span> LogisticRegression</span>\n<span id="cb8-5"><a href="#cb8-5" aria-hidden="true" tabindex="-1"></a><span class="im">from</span> sklearn.dummy <span class="im">import</span> DummyClassifier</span>\n<span id="cb8-6"><a href="#cb8-6" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-7"><a href="#cb8-7" aria-hidden="true" tabindex="-1"></a>data <span class="op">=</span> load_breast_cancer()</span>\n<span id="cb8-8"><a href="#cb8-8" aria-hidden="true" tabindex="-1"></a>X_tr, X_te, y_tr, y_te <span class="op">=</span> train_test_split(</span>\n<span id="cb8-9"><a href="#cb8-9" aria-hidden="true" tabindex="-1"></a>    data.data, data.target, test_size<span class="op">=</span><span class="fl">0.2</span>, stratify<span class="op">=</span>data.target, random_state<span class="op">=</span>RANDOM_STATE)</span>\n<span id="cb8-10"><a href="#cb8-10" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-11"><a href="#cb8-11" aria-hidden="true" tabindex="-1"></a>baseline <span class="op">=</span> DummyClassifier(strategy<span class="op">=</span><span class="st">&quot;most_frequent&quot;</span>).fit(X_tr, y_tr)</span>\n<span id="cb8-12"><a href="#cb8-12" aria-hidden="true" tabindex="-1"></a>model <span class="op">=</span> make_pipeline(StandardScaler(), LogisticRegression(max_iter<span class="op">=</span><span class="dv">2000</span>))</span>\n<span id="cb8-13"><a href="#cb8-13" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-14"><a href="#cb8-14" aria-hidden="true" tabindex="-1"></a>cv <span class="op">=</span> cross_val_score(model, X_tr, y_tr, cv<span class="op">=</span>KFold(<span class="dv">5</span>, shuffle<span class="op">=</span><span class="va">True</span>, random_state<span class="op">=</span>RANDOM_STATE))</span>\n<span id="cb8-15"><a href="#cb8-15" aria-hidden="true" tabindex="-1"></a>model.fit(X_tr, y_tr)</span>\n<span id="cb8-16"><a href="#cb8-16" aria-hidden="true" tabindex="-1"></a></span>\n<span id="cb8-17"><a href="#cb8-17" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;Baseline (самый частый класс): </span><span class="sc">{</span>baseline<span class="sc">.</span>score(X_te, y_te)<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-18"><a href="#cb8-18" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;Кросс-валидация на train:      </span><span class="sc">{</span>cv<span class="sc">.</span>mean()<span class="sc">:.3f}</span><span class="ss"> ± </span><span class="sc">{</span>cv<span class="sc">.</span>std()<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span>\n<span id="cb8-19"><a href="#cb8-19" aria-hidden="true" tabindex="-1"></a><span class="bu">print</span>(<span class="ss">f&quot;Финальная оценка на test:      </span><span class="sc">{</span>model<span class="sc">.</span>score(X_te, y_te)<span class="sc">:.3f}</span><span class="ss">&quot;</span>)</span></code></pre></div>\n<div class="output stream stdout">\n<pre><code>Baseline (самый частый класс): 0.632\nКросс-валидация на train:      0.971 ± 0.024\nФинальная оценка на test:      0.982\n</code></pre>\n</div>\n</div>\n<div id="7581482e" class="cell markdown">\n<p><strong>Главное правило курса:</strong> тестовую выборку смотрят один\nраз, в самом конце. Всё остальное — подбор модели, признаков и\nгиперпараметров — только по кросс-валидации.</p>\n</div>\n</body>\n</html>\n'}}]);